"use client";

import React, { useRef, useEffect, useState, useCallback } from "react";
import gsap from "gsap";
import { Draggable } from "gsap/Draggable";
import { InertiaPlugin } from "gsap/InertiaPlugin";
import { useGSAP } from "@gsap/react";
import "./draggable-grid.css";

if (typeof window !== "undefined") {
  gsap.registerPlugin(Draggable, InertiaPlugin);
}

export interface GridItem {
  /** Unique identifier */
  id: string | number;
  /** Image source URL */
  image: string;
  /** Data identifier for grouping/categorization */
  dataId?: string | number;
  /** Alt text for image */
  alt?: string;
}

export interface DraggableGridProps {
  /** Array of items to display in the grid */
  items: GridItem[];
  /** Number of columns in the grid */
  columns?: number;
  /** Enable drag functionality */
  enableDrag?: boolean;
  /** Enable mouse wheel scrolling */
  enableWheel?: boolean;
  /** Edge resistance when dragging (0-1) */
  edgeResistance?: number;
  /** Intro animation duration in seconds */
  introDuration?: number;
  /** Callback when an item is clicked */
  onItemClick?: (item: GridItem, index: number) => void;
  /** Additional CSS classes for the main container */
  className?: string;
  /** Additional CSS classes for grid container */
  gridClassName?: string;
  /** Additional CSS classes for individual items */
  itemClassName?: string;
  /** Bounds padding in pixels */
  boundsPadding?: { x: number; y: number };
  /** Container mode - 'fixed' for full viewport, 'absolute' for contained */
  containerMode?: "fixed" | "absolute";
  /** Scale factor for the entire grid (0.5 = half size, 2 = double size) */
  scale?: number;
  /** Gap between items in vw units */
  gap?: number;
  /** Wheel scroll smoothing duration in seconds (0.1-1.0) */
  wheelSmoothing?: number;
}

const DraggableGrid: React.FC<DraggableGridProps> = ({
  items,
  columns = 10,
  enableDrag = true,
  enableWheel = true,
  edgeResistance = 0.9,
  introDuration = 1.2,
  onItemClick,
  className = "",
  gridClassName = "",
  itemClassName = "",
  boundsPadding = { x: 200, y: 100 },
  containerMode = "absolute",
  scale = 1,
  gap = 5,
  wheelSmoothing = 0.3,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const draggableInstanceRef = useRef<Draggable | null>(null);
  const observerRef = useRef<IntersectionObserver | null>(null);
  const hasInitializedRef = useRef(false);

  const columnedItems = React.useMemo(() => {
    const cols: GridItem[][] = Array.from({ length: columns }, () => []);
    items.forEach((item, index) => {
      cols[index % columns].push(item);
    });
    return cols;
  }, [items, columns]);

  const getContainerDimensions = useCallback(() => {
    if (containerMode === "fixed") {
      return {
        width: window.innerWidth,
        height: window.innerHeight,
      };
    } else {
      return {
        width: containerRef.current?.offsetWidth || window.innerWidth,
        height: containerRef.current?.offsetHeight || window.innerHeight,
      };
    }
  }, [containerMode]);

  const setupDraggable = () => {
    if (!gridRef.current || !enableDrag) return;

    const gridWidth = gridRef.current.offsetWidth;
    const gridHeight = gridRef.current.offsetHeight;
    const { width: containerWidth, height: containerHeight } =
      getContainerDimensions();

    const instances = Draggable.create(gridRef.current, {
      type: "x,y",
      bounds: {
        minX: -(gridWidth - containerWidth) - boundsPadding.x,
        maxX: boundsPadding.x,
        minY: -(gridHeight - containerHeight) - boundsPadding.y,
        maxY: boundsPadding.y,
      },
      inertia: true,
      allowEventDefault: true,
      edgeResistance,
      onDragStart: () => {
        setIsDragging(true);
      },
      onDragEnd: () => {
        setIsDragging(false);
      },
    });

    draggableInstanceRef.current = instances[0];
  };

  const setupObserver = () => {
    if (!gridRef.current) return;

    observerRef.current = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            gsap.to(entry.target, {
              scale: 1,
              opacity: 1,
              duration: 0.5,
              ease: "power2.out",
            });
          } else {
            gsap.to(entry.target, {
              opacity: 0,
              scale: 0.5,
              duration: 0.5,
              ease: "power2.in",
            });
          }
        });
      },
      {
        root: containerMode === "absolute" ? containerRef.current : null,
        threshold: 0.1,
      },
    );

    const productDivs = gridRef.current.querySelectorAll(".product > div");
    productDivs.forEach((div) => {
      observerRef.current?.observe(div);
    });
  };

  useGSAP(
    () => {
      if (
        !containerRef.current ||
        !gridRef.current ||
        hasInitializedRef.current
      )
        return;

      requestAnimationFrame(() => {
        if (!containerRef.current || !gridRef.current) return;

        hasInitializedRef.current = true;

        const productDivs = gridRef.current.querySelectorAll(".product > div");

        if (productDivs.length === 0) return;

        const gridWidth = gridRef.current.offsetWidth;
        const gridHeight = gridRef.current.offsetHeight;
        const { width: containerWidth, height: containerHeight } =
          getContainerDimensions();

        const centerX = (containerWidth - gridWidth) / 2;
        const centerY = (containerHeight - gridHeight) / 2;

        gsap.set(gridRef.current, { x: centerX, y: centerY });

        const timeline = gsap.timeline();

        timeline.set(containerRef.current, { scale: 0.5 });
        timeline.set(productDivs, {
          scale: 0.5,
          opacity: 0,
        });

        timeline.to(productDivs, {
          scale: 1,
          opacity: 1,
          duration: 0.6,
          ease: "power3.out",
          stagger: {
            amount: introDuration,
            from: "random",
          },
        });

        timeline.to(containerRef.current, {
          scale: 1,
          duration: introDuration,
          ease: "power3.inOut",
          onComplete: () => {
            setupDraggable();
            setupObserver();
            setIsLoaded(true);
          },
        });
      });
    },
    { scope: containerRef, dependencies: [items.length] },
  );

  useEffect(() => {
    if (!isLoaded) return;

    const updateBounds = () => {
      if (!draggableInstanceRef.current || !gridRef.current) return;

      const gridWidth = gridRef.current.offsetWidth;
      const gridHeight = gridRef.current.offsetHeight;
      const { width: containerWidth, height: containerHeight } =
        getContainerDimensions();

      draggableInstanceRef.current.vars.bounds = {
        minX: -(gridWidth - containerWidth) - boundsPadding.x,
        maxX: boundsPadding.x,
        minY: -(gridHeight - containerHeight) - boundsPadding.y,
        maxY: boundsPadding.y,
      };
    };

    window.addEventListener("resize", updateBounds);
    return () => {
      window.removeEventListener("resize", updateBounds);
    };
  }, [isLoaded, boundsPadding, containerMode, getContainerDimensions]);

  useEffect(() => {
    if (!enableWheel || !containerRef.current || !isLoaded) return;

    const container = containerRef.current;

    const handleWheel = (e: WheelEvent) => {
      if (!gridRef.current || !draggableInstanceRef.current) return;

      const deltaX = -e.deltaX * 7;
      const deltaY = -e.deltaY * 7;

      const currentX = gsap.getProperty(gridRef.current, "x") as number;
      const currentY = gsap.getProperty(gridRef.current, "y") as number;

      const newX = currentX + deltaX;
      const newY = currentY + deltaY;

      const bounds = draggableInstanceRef.current.vars.bounds as {
        minX: number;
        maxX: number;
        minY: number;
        maxY: number;
      };

      const clampedX = Math.max(bounds.minX, Math.min(bounds.maxX, newX));
      const clampedY = Math.max(bounds.minY, Math.min(bounds.maxY, newY));

      const canScrollX =
        (deltaX > 0 && currentX < bounds.maxX) ||
        (deltaX < 0 && currentX > bounds.minX);
      const canScrollY =
        (deltaY > 0 && currentY < bounds.maxY) ||
        (deltaY < 0 && currentY > bounds.minY);

      if (canScrollX || canScrollY) {
        e.preventDefault();
      } else {
        return;
      }

      gsap.to(gridRef.current, {
        x: clampedX,
        y: clampedY,
        duration: wheelSmoothing,
        ease: "power3.out",
      });
    };

    container.addEventListener("wheel", handleWheel, { passive: false });

    return () => {
      container.removeEventListener("wheel", handleWheel);
    };
  }, [enableWheel, isLoaded, wheelSmoothing]);

  useEffect(() => {
    return () => {
      if (draggableInstanceRef.current) {
        draggableInstanceRef.current.kill();
      }
      if (observerRef.current) {
        observerRef.current.disconnect();
      }
    };
  }, []);

  const handleItemClick = (
    item: GridItem,
    index: number,
    e: React.MouseEvent,
  ) => {
    if (isDragging) return;
    e.stopPropagation();
    onItemClick?.(item, index);
  };

  const itemSize = `${18.5 * scale}vw`;
  const gapSize = `${gap * scale}vw`;
  const columnOffset = `${gap * 2 * scale}vw`;

  return (
    <div
      ref={containerRef}
      className={`draggable-grid-container ${containerMode === "fixed" ? "fixed-mode" : "absolute-mode"} ${className}`}
    >
      <div
        ref={gridRef}
        className={`draggable-grid ${isLoaded && enableDrag && !isDragging ? "draggable" : ""} ${isDragging ? "dragging" : ""} ${gridClassName}`}
        style={{ columnGap: gapSize }}
      >
        {columnedItems.map((column, colIndex) => (
          <div
            key={colIndex}
            className="draggable-grid-column"
            style={{
              rowGap: gapSize,
              marginTop: colIndex % 2 === 1 ? columnOffset : "0",
            }}
          >
            {column.map((item, itemIndex) => {
              const globalIndex = colIndex + itemIndex * columns;
              return (
                <div
                  key={item.id}
                  className={`product ${itemClassName}`}
                  style={{ width: itemSize }}
                  onClick={(e) => handleItemClick(item, globalIndex, e)}
                >
                  <div
                    className="product-inner"
                    style={{ width: itemSize }}
                    data-id={item.dataId}
                  >
                    <img
                      src={item.image}
                      alt={item.alt || `Item ${item.id}`}
                      className="product-image object-cover"
                      draggable={false}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
};

export default DraggableGrid;

.draggable-grid-container {
  overflow: hidden;
  transform-origin: center center;
  will-change: transform;
}

.draggable-grid-container.fixed-mode {
  position: fixed;
  width: 100vw;
  height: 100vh;
  top: 0;
  left: 0;
}

.draggable-grid-container.absolute-mode {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.draggable-grid {
  position: absolute;
  width: max-content;
  height: max-content;
  display: flex;
  will-change: transform;
}

.draggable-grid.draggable {
  cursor: grab;
}

.draggable-grid.dragging {
  cursor: grabbing;
}

.draggable-grid-column {
  display: flex;
  flex-direction: column;
}

.draggable-grid-column.offset {
  margin-top: 10vw;
}

.product {
  position: relative;
  aspect-ratio: 1 / 1;
}

.product-inner {
  aspect-ratio: 1 / 1;
  will-change: transform;
}

.product-image {
  position: absolute;
  width: 100%;
  height: 100%;
  object-fit: contain;
  will-change: transform;
  transition: transform 300ms ease-in-out;
  user-select: none;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  pointer-events: none;
}

.product:hover .product-image {
  transform: scale(1.05);
}

.draggable-grid.dragging * {
  user-select: none;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
}

@media (prefers-reduced-motion: reduce) {
  .draggable-grid,
  .product-inner,
  .product-image {
    transition: none !important;
  }
}
